export type GuardianShareDeclined = Envelope<"guardian.share.declined", 1, GuardianShareDeclinedPayload>;

/**
 * PHONE ONLY. Sentinel captured the conversation around a flag, with real text.
 */
export type SentinelCaptureReady = Envelope<"sentinel.capture.ready", 1, SentinelCaptureReadyPayload>;

/**
 * PHONE ONLY. The child is in a watched conversation now (drives the keyboard companion).
 */
export type SentinelConversationActive = Envelope<"sentinel.conversation.active", 1, SentinelConversationActivePayload>;

/**
 * Sentinel revised a flag, e.g. after more context or a cloud analysis.
 */
export type SentinelFlagUpdated = Envelope<"sentinel.flag.updated", 1, SentinelFlagUpdatedPayload>;

/**
 * Sentinel flagged an incoming message as harmful.
 */
export type SentinelMessageFlagged = Envelope<"sentinel.message.flagged", 1, SentinelMessageFlaggedPayload>;

export type KuumaEvent =
  | CasefileCaseEscalated
  | CasefileCaseUpdated
  | CasefileEvidenceSealed
  | CasefileReportReady
  | CasefileShareCompleted
  | CasefileShareRequested
  | CompanionAdviceShown
  | CompanionCaptureRequested
  | CompanionFeedbackSubmitted
  | CompanionSosTriggered
  | GuardianAlertSent
  | GuardianPairingCompleted
  | GuardianPolicyUpdated
  | GuardianReportRequested
  | GuardianShareApproved
  | GuardianShareDeclined
  | SentinelCaptureReady
  | SentinelConversationActive
  | SentinelFlagUpdated
  | SentinelMessageFlagged;

export type PhoneOnlyEvent =
  | CasefileReportReady
  | GuardianReportRequested
  | SentinelCaptureReady
  | SentinelConversationActive;

/** Events that may leave the phone. */
export type CloudSendableEvent = Exclude<KuumaEvent, PhoneOnlyEvent>;

export const namespaceValues = ["casefile", "companion", "guardian", "sentinel"] as const;
export type Namespace = (typeof namespaceValues)[number];

